const deal = $('Deal Proposal Stage Webhook').first().json;
const config = $('Get Config').first().json;
const props = deal.properties || deal;

return [{
  json: {
    clientName: props.dealname || props.name || '',
    company: props.company || props.dealname || '',
    industry: props.industry || '',
    painPoints: props.deal_pain_points || props.painPoints || '',
    dealValue: props.amount || 0,
    tier: props.tier || 'starter',
    dealId: deal.id || deal.dealId || '',
    contactEmail: props.contact_email || props.email || '',
    contactFirstName: props.contact_firstname || props.firstName || '',
    driveFolderId: props.client_drive_folder_id || '',
    config
  }
}];

const d = $('Extract Deal Data').first().json;
const tierInfo = d.config.tiers[d.tier] || d.config.tiers.starter;

return [{
  json: {
    systemPrompt: 'You are writing consulting proposals for IntraWeb Technologies LLC. Positioning: the implementation layer for AI-enabled operations. We don't advise â€” we build. Tone: direct, confident, no corporate speak, no em dashes. Use specific outcomes and real numbers. Return ONLY the main proposal body as clean semantic HTML: no DOCTYPE, no html/head/body tags, no markdown, no backticks. Start with the first section (e.g. Executive Summary). Use headings (h2, h3), paragraphs, and lists. The content will be wrapped in a branded template. CRITICAL: Use ONLY the package and numbers provided in the user message for the Investment section. Do not mention or suggest any other package. CRITICAL: Include the customer's pain points in the proposal. The Problem section must reflect their stated pain points (use their words where appropriate); What We'll Build must tie solutions directly to those pain points. Do not omit or generalize the pain pointsâ€”the customer should see their situation clearly reflected.',
    userPrompt: `Write a full consulting proposal for:

Client: ${d.clientName}
Company: ${d.company}
Industry: ${d.industry}
Deal Value: $${d.dealValue}

CUSTOMER PAIN POINTS (include these in the proposalâ€”use in The Problem section and tie What We'll Build to them):
${d.painPoints || '(None provided)'}

PACKAGE (use this and only this in the Investment section): ${tierInfo.name} â€” $${tierInfo.monthlyPrice}/month + $${tierInfo.setupFee} one-time setup. Do not mention Starter, Growth, or Ops by name except to state that this proposal is for the ${tierInfo.name} package. The numbers in your Investment section must be exactly $${tierInfo.monthlyPrice}/mo and $${tierInfo.setupFee} setup.

Include these sections:
1. Executive Summary
2. The Problem (reflect the customer's pain points above; use their language where it fits)
3. What We'll Build (specific automations that address each pain point)
4. Timeline (8-week implementation)
5. Investment (use only the ${tierInfo.name} figures above: $${tierInfo.monthlyPrice}/mo, $${tierInfo.setupFee} setup)
6. Why IntraWeb
7. Next Steps

Make it specific to their industry. Return only the HTML body content, no wrapper.`,
    maxTokens: 4000
  }
}];

const raw = $('Call Claude API').first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) ? raw.content[0].text : '';
const d = $('Extract Deal Data').first().json;
return [{ json: { data: { text }, html: text, fileName: `IntraWeb â€” ${d.clientName} â€” Proposal.pdf` } }];

const claudeResult = $('Parse Claude Response').first().json;
const d = $('Extract Deal Data').first().json;
const config = d.config || {};
const branding = config.branding || {};
const logoUrl = branding.logoUrl || '';
const companyName = (config.owner && config.owner.companyName) ? config.owner.companyName : 'IntraWeb Technologies LLC';
const bodyContent = (claudeResult.data ? claudeResult.data.text : claudeResult.html || '').trim();
const clientName = d.clientName || 'Client';

const html = `<!DOCTYPE html>
<html lang=\"en\">
<head>
  <meta charset=\"UTF-8\">
  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">
  <title>${companyName} â€” Proposal for ${clientName}</title>
  <link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">
  <style>
    * { box-sizing: border-box; }
    body { font-family: 'DM Sans', sans-serif; color: #1a1f2e; max-width: 720px; margin: 0 auto; padding: 36px 40px; line-height: 1.55; font-size: 14px; }
    .header { display: flex; align-items: center; gap: 14px; margin-bottom: 24px; padding-bottom: 16px; border-bottom: 2px solid #E87B2B; }
    .header img { height: 44px; width: auto; display: block; }
    .header-text { }
    .company-name { font-size: 17px; font-weight: 700; color: #6B4E9B; margin: 0; }
    .proposal-title { font-size: 13px; color: #5a6578; margin: 2px 0 0 0; }
    .proposal-body { margin-top: 0; padding: 0; }
    .proposal-body h2 { color: #6B4E9B; font-size: 18px; margin: 20px 0 8px 0; }
    .proposal-body h3 { color: #1a1f2e; font-size: 15px; margin: 14px 0 6px 0; }
    .proposal-body p { margin: 0 0 10px 0; }
    .proposal-body ul, .proposal-body ol { margin: 0 0 10px 0; padding-left: 20px; }
    .proposal-body li { margin-bottom: 4px; }
    .highlight { background: #f5f2f8; border-left: 4px solid #E87B2B; padding: 10px 14px; margin: 12px 0; border-radius: 0 4px 4px 0; }
    .cta { background: linear-gradient(135deg, #6B4E9B 0%, #5a3d84 100%); color: #fff; padding: 16px 20px; margin-top: 20px; border-radius: 6px; text-align: center; }
  </style>
</head>
<body>
  <div class=\"header\">
    ${logoUrl ? `<img src=\"${logoUrl}\" alt=\"IntraWeb\" />` : '<span style=\"font-size:28px;font-weight:700;color:#6B4E9B\">I</span><span style=\"font-size:28px;font-weight:700;color:#E87B2B\">W</span>'}
    <div class=\"header-text\">
      <p class=\"company-name\">${companyName}</p>
      <p class=\"proposal-title\">Proposal for ${clientName}</p>
    </div>
  </div>
  <div class=\"proposal-body\">
    ${bodyContent}
  </div>
</body>
</html>`;

return [{ json: { html, fileName: `IntraWeb â€” ${d.clientName} â€” Proposal.pdf` } }];

const item = $input.first();
const fileName = $('Prep PDF Input').first().json.fileName || 'document.pdf';
return [{ json: { fileName }, binary: item.binary ? { ...item.binary } : {} }];

const d = $('Extract Deal Data').first().json;
const driveLink = 'https://drive.google.com/file/d/' + $('Upload to Drive').first().json.id;

return [{
  json: {
    message: `Proposal ready for ${d.clientName} â€” set Status to Approved to send: ${driveLink}`,
    priority: 'info'
  }
}];

const d = $('Extract Deal Data').first().json;
const driveLink = 'https://drive.google.com/file/d/' + $('Upload to Drive').first().json.id;

return [{
  json: {
    to: d.contactEmail,
    subject: `Your IntraWeb proposal is ready â€” ${d.clientName}`,
    html: `<p>Hi ${d.contactFirstName || 'there'},</p><p>Your proposal is attached. I've outlined exactly what we'll build, the timeline, and the investment.</p><p>You can also <a href="${driveLink}">view it in Google Drive here</a>.</p><p>Take a look and let me know if you have any questions. When you're ready to move forward, reply to this email and I'll send the contract for e-signature.</p><p>â€” John<br/>${d.config.owner.companyName}</p>`,
    workflowName: 'SYS 05: Proposal & Contract Delivery'
  }
}];

return [{
  json: {
    workflowName: 'SYS 05: Proposal & Contract Delivery',
    contactName: $('Extract Deal Data').first().json.clientName,
    phone: '',
    eventType: 'proposal_sent',
    status: 'success',
    notes: `Deal value: $${$('Extract Deal Data').first().json.dealValue}`
  }
}];
